// test-client.js
// Runs several cases at once: different domains, a real second sequence,
// and deliberate error cases — so you see the full behavior in one run,
// not just the happy path.
// Run: npm test  (make sure `npm run dev` is running in another terminal first)

const BASE_URL = "http://localhost:4500/call-genes";

const TEST_SEQUENCE_1 =
  "ATGACCATGATTACGGATTCACTGGCCGTCGTTTTACAACGTCGTGACTGGGAAAACCCTGGCGTTACCCAACTTAATCGCCTTGCAGCACATCCCCCTTTCGCCAGCTGGCGTAATAGCGAAGAGGCCCGCACCGATCGCCCTTCCCAACAGTTGCGCAGCCTGAATGGCGAATGGCGCCTGA";

// A different real bacterial gene fragment (E. coli thrA start region) — swap
// in any FASTA sequence of your own here to test with new data.
const TEST_SEQUENCE_2 =
  "";

async function callGeneCaller(sequence, domain) {
  const res = await fetch(BASE_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ sequence, domain }),
  });
  const data = await res.json();
  return { status: res.status, data };
}

async function run() {
  console.log("── Case 1: bacterial, known-good sequence ──");
  console.log(await callGeneCaller(TEST_SEQUENCE_1, "bacterial"));

  console.log("\n── Case 2: bacterial, a different real gene (E. coli thrA region) ──");
  console.log(await callGeneCaller(TEST_SEQUENCE_2, "bacterial"));

  console.log("\n── Case 3: same sequence, marked eukaryotic (check confidence drops) ──");
  console.log(await callGeneCaller(TEST_SEQUENCE_1, "eukaryotic"));

  console.log("\n── Case 4: unknown domain (should fall back, confidence 'low') ──");
  console.log(await callGeneCaller(TEST_SEQUENCE_1, "unknown"));

  console.log("\n── Case 5: no ATG at all (should return empty genes array, not an error) ──");
  console.log(await callGeneCaller("CCCCCCCCCCCCCCCCCCCC", "bacterial"));

  console.log("\n── Case 6: invalid domain (should 400, with a clear error message) ──");
  console.log(await callGeneCaller(TEST_SEQUENCE_1, "martian"));

  console.log("\n── Case 7: missing sequence entirely (should 400) ──");
  const res = await fetch(BASE_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ domain: "bacterial" }),
  });
  console.log({ status: res.status, data: await res.json() });
}

run().catch((err) => {
  console.error("Could not reach service — is `npm run dev` running in another terminal?");
  console.error(err.message);
});